#include "../include/optimizer.hpp"
#include "../include/parser.hpp"
#include <iostream>
#include <vector>

void test_optimizer() {
    std::cout << "\n--- Testing Optimizer ---\n";
    
    // First, ensure we have some data generated by the parser
    Input input;
    Test test;
    Parser parser;
    parser.tokenization(input, test);
    std::vector<std::bfloat16_t> embedded = parser.embedding(input, test);
    std::cout << "Generated " << embedded.size() << " bfloat16_t elements to disk.\n";

    Optimizer optimizer;
    Portion portion;
    
    // Use smaller sizes for the test so we can observe the sliding window behavior
    portion.ram_buffer_size = 32; // 32 floats = 8 tokens
    portion.context_window_size = 4; // 4 tokens per window

    std::cout << "Initial buffer states:\n";
    std::cout << "  ram_buffer_tokens size: " << portion.ram_buffer_tokens.size() << "\n";

    std::cout << "Running disk_to_ram...\n";
    optimizer.disk_to_ram(portion);
    
    std::cout << "After disk_to_ram:\n";
    std::cout << "  ram_buffer_tokens size: " << portion.ram_buffer_tokens.size() << "\n";

    bool training_in_use = false;
    std::cout << "Running ram_to_contextWindow...\n";
    optimizer.ram_to_contextWindow(portion, training_in_use);
    
    std::cout << "After ram_to_contextWindow:\n";
    std::cout << "  ram_buffer_tokens size: " << portion.ram_buffer_tokens.size() << " (Should be modified or cleared by disk_to_ram ownership)\n";
    std::cout << "  context_window_tokens size: " << portion.context_window_tokens.size() << " (Should be " << portion.context_window_size * 4 << ")\n";
    std::cout << "  target_tokens size: " << portion.target_tokens.size() << " (Should be 4)\n";

    std::cout << "Optimizer tests finished successfully!\n";
}
